/**
 * Typed outcome of a `dispatch_action` call.
 *
 * Exactly one of `correlation_id` (accepted) or `error` (rejected/failed)
 * will be `Some`. `code` is `Some` only for coded rejections — it carries
 * the stable machine-readable token (issue #1734) alongside the
 * human-readable `error`. This field is load-bearing:
 * `nmp-ffi`'s `coded_rejection_tests.rs:122` guards the same invariant on
 * the C-ABI side.
 */
public struct DispatchOutcome {
    public var correlationId: String?
    public var error: String?
    /**
     * Machine-readable code for coded rejections; `None` for plain errors.
     */
    public var code: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(correlationId: String?, error: String?, 
        /**
         * Machine-readable code for coded rejections; `None` for plain errors.
         */code: String?) {
        self.correlationId = correlationId
        self.error = error
        self.code = code
    }
}

#if compiler(>=6)
extension DispatchOutcome: Sendable {}
#endif


extension DispatchOutcome: Equatable, Hashable {
    public static func ==(lhs: DispatchOutcome, rhs: DispatchOutcome) -> Bool {
        if lhs.correlationId != rhs.correlationId {
            return false
        }
        if lhs.error != rhs.error {
            return false
        }
        if lhs.code != rhs.code {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(correlationId)
        hasher.combine(error)
        hasher.combine(code)
    }
}



