/**
 * Rust→shell push interface: receives NMPU FlatBuffers update frames.
 *
 * Implementations MUST NOT call back into any `NmpApp` method from within
 * `on_update` — reentrancy is forbidden (the quiescence gate would deadlock).
 */
public protocol UpdateSink: AnyObject, Sendable {
    
    /**
     * Called on every NMPU frame emitted by the runtime.
     *
     * `frame` is a copy of the original `&[u8]` — the copy is made BEFORE the
     * foreign call so no Rust state is held across the Swift/Kotlin call.
     */
    func onUpdate(frame: Data) 
    
}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceUpdateSink {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceUpdateSink] = [UniffiVTableCallbackInterfaceUpdateSink(
        onUpdate: { (
            uniffiHandle: UInt64,
            frame: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceUpdateSink.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onUpdate(
                     frame: try FfiConverterData.lift(frame)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            let result = try? FfiConverterCallbackInterfaceUpdateSink.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface UpdateSink: handle missing in uniffiFree")
            }
        }
    )]
}

private func uniffiCallbackInitUpdateSink() {
    uniffi_nmp_uniffi_fn_init_callback_vtable_updatesink(UniffiCallbackInterfaceUpdateSink.vtable)
}

